import XCTest

class BlueskyRepostUITest: XCTestCase {
    let app = XCUIApplication(bundleIdentifier: "xyz.blueskyweb.app")

    override func setUp() {
        super.setUp()
        continueAfterFailure = false
    }

    func testRepostFirstPost() {
        // Bring app to foreground
        XCUIApplication(bundleIdentifier: "xyz.blueskyweb.app").activate()

        // Get first post's repost button
        // Look for buttons with "Repost" in the label or ID
        let repostButtons = app.buttons.matching(NSPredicate(format: "label CONTAINS 'Repost' OR identifier CONTAINS 'repost'"))

        // Should find at least one repost button for the first post
        XCTAssertGreaterThan(repostButtons.count, 0, "Should find repost button(s)")

        if repostButtons.count > 0 {
            let firstRepostButton = repostButtons.element(boundBy: 0)
            XCTAssertTrue(firstRepostButton.exists, "First repost button should exist")

            if firstRepostButton.isHittable {
                firstRepostButton.tap()

                // Wait for and tap confirmation button
                let confirmButton = app.buttons["Repost"]
                let confirmExists = confirmButton.waitForExistence(timeout: 2.0)
                XCTAssertTrue(confirmExists, "Confirm button should exist")

                if confirmExists && confirmButton.isHittable {
                    confirmButton.tap()

                    // Verify success by checking that the button was tapped
                    sleep(1)  // Wait for action to complete
                }
            }
        }
    }
}

